/**
 * Alpha Engine → bot decision → paper execution → broker confirmation → trade history.
 *
 * Real code under test: engine client (over HTTP), research trace verification, decision
 * policy, bot engine, atomic decision/execution link, order worker, M6 final eligibility
 * boundary, FIFO accounting, and the Fastify trade-history routes.
 * Stand-ins: an HTTP fake of Alpha Engine serving traces generated by Alpha Engine's own
 * Python code, an in-memory database, and a scripted paper broker. No real broker, no
 * network beyond localhost, and no live trading.
 */
import { describe, it, expect, vi, beforeAll, beforeEach, afterAll } from 'vitest'
import http from 'node:http'
import { readFileSync } from 'node:fs'
import request from 'supertest'
import { createMemoryPrisma } from '../support/memoryPrisma.js'

const h = vi.hoisted(() => ({ db: null, brokers: new Map(), risk: { approved: true } }))

vi.mock('../../../worker/src/db/prisma.js', () => ({ default: new Proxy({}, { get: (_, k) => h.db[k] }) }))
vi.mock('../../src/loaders/prisma.js', () => ({ default: new Proxy({}, { get: (_, k) => h.db[k] }) }))
vi.mock('../../../worker/src/broker/clientCache.js', () => ({ getBrokerClient: async (userId) => h.brokers.get(userId) ?? null }))
vi.mock('../../src/services/metricsService.js', () => ({ default: { processExecutionFill: async () => {} } }))
vi.mock('../../../worker/src/logger.js', () => ({ log: { info() {}, warn() {}, error() {}, debug() {} } }))
vi.mock('../../../worker/src/market/dataStream.js', () => ({ subscribe() {}, unsubscribe() {} }))
// The advisory portfolio pre-check spans many tables; the authoritative M6 boundary
// (evaluateOrderEligibility) runs for real before every broker submit.
vi.mock('../../../worker/src/risk/riskManagement.js', () => ({
  riskManager: { evaluateExecutionRisk: async () => (h.risk.approved ? { approved: true, riskScore: 0.1 } : { approved: false, riskScore: 0.9, failedChecks: ['concentration'] }) }
}))

// ── Fake Alpha Engine (HTTP) ─────────────────────────────────────────────────────

const FIXTURES = JSON.parse(readFileSync(new URL('../fixtures/alpha-engine/traces.json', import.meta.url), 'utf8'))
const INTERNAL_KEY = 'test-internal-key'
const ae = { up: true, traces: {}, rankings: [], run: {}, requests: [], failTrace: new Set(), sessionClose: {} }

function resetAlphaEngine() {
  ae.up = true
  ae.traces = structuredClone(FIXTURES.traces)
  ae.failTrace = new Set()
  ae.sessionClose = {}
  ae.requests = []
  ae.run = { intelligenceConfidenceTier: 'full', rankedUnderDegradedRun: false, runStatus: 'SUCCESS' }
  ae.rankings = Object.values(ae.traces).filter((t) => t.source.predictionId !== 'pred_spy_buy_next').map((t, i) => ({ ticker: t.source.ticker, predictionId: t.source.predictionId, timestamp: '2026-11-20T15:05:08+00:00', rank: i + 1, notActionable: true }))
}

const aeServer = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost')
  ae.requests.push(url.pathname)
  const send = (status, body) => { res.writeHead(status, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(body)) }
  if (!ae.up) return send(503, { detail: 'down for test' })
  if (req.headers['x-internal-key'] !== INTERNAL_KEY) return send(401, { detail: 'missing internal key' })
  if (url.pathname === '/api/research/latest') {
    const t = String(url.searchParams.get('ticker') ?? '').toUpperCase()
    const row = ae.rankings.find((r) => r.ticker === t)
    const base = { ticker: t, publicationId: 'pub_fixture', mode: url.searchParams.get('mode'), marketDate: '2026-11-20', publishedAt: '2026-11-20T15:05:08+00:00',
      run: { intelligenceConfidenceTier: ae.run.intelligenceConfidenceTier, rankedUnderDegradedRun: ae.run.rankedUnderDegradedRun, runStatus: ae.run.runStatus } }
    return send(200, row ? { found: true, predictionId: row.predictionId, ...base } : { found: false, reason: 'no_signal', ...base })
  }
  if (url.pathname === '/api/market/session-close') {
    const t = String(url.searchParams.get('ticker') ?? '').toUpperCase()
    const close = ae.sessionClose[t]
    return close ? send(200, { ticker: t, session: url.searchParams.get('session'), close, timeframe: '1d' }) : send(404, { detail: 'no daily bar' })
  }
  const m = url.pathname.match(/^\/api\/predictions\/([^/]+)\/trace$/)
  if (m) {
    const id = decodeURIComponent(m[1])
    if (ae.failTrace.has(id)) return send(500, { detail: 'boom' })
    return ae.traces[id] ? send(200, ae.traces[id]) : send(404, { detail: 'prediction not found' })
  }
  send(404, { detail: 'not found' })
})
await new Promise((resolve) => aeServer.listen(0, '127.0.0.1', resolve))
process.env.ENGINE_URL = `http://127.0.0.1:${aeServer.address().port}`
process.env.INTERNAL_READ_KEY = INTERNAL_KEY
process.env.RESEARCH_INDEX_TTL_MS = '0'

// ── System under test (imported after the environment is set) ────────────────────

const { FakeBroker } = await import('../support/fakePaperBroker.js')
const engine = await import('../../../worker/src/engine/botEngine.js')
const worker = await import('../../../worker/src/queues/orderWorker.js')
const { eligibilityConfig } = await import('../../../worker/src/risk/orderEligibility.js')
const { priceCache } = await import('../../../worker/src/market/priceCache.js')
const { activateEmergencyStop } = await import('../../src/services/emergencyStopService.js')
const { computeBotAccounting } = await import('../../src/services/botAccountingService.js')
const { default: createApp } = await import('../../src/loaders/fastify.js')
const { default: registerRoutes } = await import('../../src/loaders/routes.js')

const { evaluateBot, stopBotEngine, inflightMap, botEngineConfig } = engine
const { orderWorkerConfig, runOnce, claimNextExecution, recoverStuckJobs, setInflightMap } = worker

// ── Fixtures ─────────────────────────────────────────────────────────────────────

const T0 = new Date('2026-11-20T15:00:00Z') // 30 minutes after the research was observed
let app, tokenA, tokenB

beforeAll(async () => {
  vi.useFakeTimers({ toFake: ['Date'], now: T0 })
  h.db = createMemoryPrisma()
  app = await createApp()
  await registerRoutes(app)
  await app.ready()
  tokenA = app.jwt.sign({ sub: 'usr_a' })
  tokenB = app.jwt.sign({ sub: 'usr_b' })
})
afterAll(async () => {
  vi.useRealTimers()
  await app.close()
  await new Promise((resolve) => aeServer.close(resolve))
})

beforeEach(async () => {
  vi.setSystemTime(T0)
  h.db.reset()
  h.brokers.clear()
  h.risk.approved = true
  resetAlphaEngine()
  stopBotEngine()
  inflightMap.clear()
  setInflightMap(inflightMap)
  botEngineConfig.researchRecheckMs = 60_000
  Object.assign(orderWorkerConfig, {
    // Monotonic clock: each read is 1ms later, like real elapsed time (lets sweeps come due).
    sleep: async () => {}, now: () => { vi.setSystemTime(Date.now() + 1); return new Date() }, fillTimeoutMs: 0, fillPollIntervalMs: 0, reconcileIntervalMs: 0,
    notFoundGraceMs: 60_000, stuckAfterMs: 120_000, cancelPollMs: 0, maxAttempts: 3,
  })
  eligibilityConfig.maxPriceAgeMs = 5 * 60_000
  for (const id of ['usr_a', 'usr_b']) {
    await h.db.user.create({ data: { id, email: `${id}@example.test`, riskSettings: null, subscription: { status: 'ACTIVE' } } })
    await h.db.portfolio.create({ data: { id: `por_${id}`, userId: id } })
    h.brokers.set(id, new FakeBroker(id))
  }
})

async function researchBot(id = 'bot_r', { userId = 'usr_a', research = { requireEdgeOverBaseline: false }, config = {}, enabled = true } = {}) {
  return h.db.bot.create({ data: {
    id, userId, portfolioId: `por_${userId}`, name: id, enabled, botType: 'rule_based',
    config: { signalSource: 'alpha_research', tickers: ['SPY', 'QQQ', 'IWM', 'DIA'], capitalMode: 'allocated', allocatedAmount: 10_000, maxOrderNotional: 5_000, research, ...config }
  } })
}
async function loaded(id) {
  const bot = await h.db.bot.findUnique({ where: { id } })
  return { ...bot, rules: await h.db.botRule.findMany({ where: { botId: id, enabled: true } }) }
}
async function tick(botId, ticker, price) {
  priceCache.set(ticker, { last: price, bid: price, ask: price })
  await evaluateBot(await loaded(botId), ticker)
}
const advance = (ms) => vi.setSystemTime(new Date(Date.now() + ms))
async function drain(max = 20) { for (let i = 0; i < max; i++) if (!(await runOnce())) return }
const executions = (where = {}) => h.db.execution.findMany({ where, orderBy: { createdAt: 'asc' } })
const decisions = (botId = 'bot_r') => h.db.botEvent.findMany({ where: { botId, type: 'decision_made' }, orderBy: { createdAt: 'asc' } })
const skips = async (botId = 'bot_r') => (await h.db.botEvent.findMany({ where: { botId, type: 'execution_skipped' } })).map((e) => e.metadata.reason)
const audits = async (id) => (await h.db.executionAudit.findMany({ where: { executionId: id }, orderBy: { createdAt: 'asc' } })).map((a) => a.eventType)
const broker = (u = 'usr_a') => h.brokers.get(u)
const as = (token) => ({ Authorization: `Bearer ${token}` })
const history = (token, id) => request(app.server).get(`/api/executions/${id}/research`).set(as(token))

// ── 1. The full lifecycle ────────────────────────────────────────────────────────

describe('prediction → decision → paper execution → broker confirmation → trade history', () => {
  it('trades verified research once and shows the original evidence in trade history', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540.5)

    // Decision: accepted, research-derived direction and confidence, evidence captured and linked.
    const [exe] = await executions()
    expect(exe).toMatchObject({ ticker: 'SPY', direction: 'buy', quantity: 9, status: 'queued', origin: 'bot', signalScore: 0.82, clientOrderId: `tp_${exe.id}` })
    const [decision] = await decisions()
    expect(decision).toMatchObject({ executionId: exe.id })
    expect(decision.metadata).toMatchObject({
      decision: 'accepted', predictionId: 'pred_spy_buy', ticker: 'SPY',
      researchIntegrity: { sha256: FIXTURES.traces.pred_spy_buy.evidence.sha256, verifiedAtCapture: true },
      decisionContext: { reason: 'research_accepted', signal: 'buy', researchConfidence: 0.82, confidenceIsProbability: false, executionId: exe.id }
    })
    expect(decision.metadata.researchCanonicalJson).toBe(FIXTURES.traces.pred_spy_buy.evidence.canonicalJson)
    expect(ae.requests).toEqual(['/api/research/latest', '/api/predictions/pred_spy_buy/trace'])

    // Paper execution and broker confirmation (submit, then the reconciliation sweep sees the fill).
    await drain()
    expect((await h.db.execution.findUnique({ where: { id: exe.id } })).status).toBe('submitted')
    broker().fill(exe.clientOrderId, 9, 540.42)
    await drain()
    const filled = await h.db.execution.findUnique({ where: { id: exe.id } })
    expect(filled).toMatchObject({ status: 'filled', filledQuantity: 9, filledPrice: 540.42 })
    expect(broker().submitCalls).toBe(1)
    expect(await audits(exe.id)).toEqual(['execution_created', 'claimed', 'submit_attempted', 'submit_confirmed', 'filled'])
    const created = await h.db.executionAudit.findFirst({ where: { executionId: exe.id, eventType: 'execution_created' } })
    expect(created.metadata.research).toMatchObject({ predictionId: 'pred_spy_buy', decisionEventId: decision.id, evidenceSha256: FIXTURES.traces.pred_spy_buy.evidence.sha256 })

    // Trade history: the fill, and the research it was traded on, verified from the archive.
    const list = await request(app.server).get('/api/executions').set(as(tokenA))
    expect(list.status).toBe(200)
    expect(list.body.data.map((e) => [e.id, e.status, e.filledPrice])).toEqual([[exe.id, 'filled', 540.42]])
    const res = await history(tokenA, exe.id)
    expect(res.status).toBe(200)
    expect(res.body.data).toMatchObject({
      status: 'verified_digest', executionId: exe.id, botId: 'bot_r', decisionEventId: decision.id, predictionId: 'pred_spy_buy', decision: 'accepted',
      researchTrace: FIXTURES.traces.pred_spy_buy.decisionReference
    })
    expect(res.body.data.evidence).toEqual(FIXTURES.traces.pred_spy_buy.evidence.snapshot)

    // Accounting reflects the broker-confirmed fill.
    const acct = await computeBotAccounting('bot_r')
    expect(acct.openPositions.SPY).toMatchObject({ quantity: 9 })

    // Trade history is archival: changing research upstream afterwards changes nothing.
    ae.traces.pred_spy_buy.evidence.snapshot.confidence = 0.1
    expect((await history(tokenA, exe.id)).body.data.evidence.confidence).toBe(0.82)
  })

  it('never trades the same prediction twice, including after a worker restart', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    await drain()
    broker().fill((await executions())[0].clientOrderId, 9, 540)
    await drain()

    advance(61_000)
    await tick('bot_r', 'SPY', 540)
    stopBotEngine() // restart: in-memory state is gone; the database decides
    advance(61_000)
    await tick('bot_r', 'SPY', 540)

    expect(await executions()).toHaveLength(1)
    expect((await decisions()).filter((d) => d.metadata.decision === 'accepted')).toHaveLength(1)
    expect(await skips()).toContain('prediction_already_acted')
  })

  it('acts on a newer prediction for the same ticker', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    await drain()
    broker().fill((await executions())[0].clientOrderId, 9, 540)
    await drain()

    // The next pipeline run publishes a newer SPY prediction.
    ae.rankings = ae.rankings.map((r) => (r.ticker === 'SPY' ? { ...r, predictionId: 'pred_spy_buy_next' } : r))
    advance(61_000)
    await tick('bot_r', 'SPY', 541)
    const [first, second] = await executions()
    expect(second).toMatchObject({ ticker: 'SPY', direction: 'buy', signalScore: 0.77 })
    expect((await history(tokenA, first.id)).body.data.predictionId).toBe('pred_spy_buy')
    expect((await history(tokenA, second.id)).body.data).toMatchObject({ status: 'verified_digest', predictionId: 'pred_spy_buy_next' })
  })

  it('rejects a trace relabelled with another prediction id', async () => {
    await researchBot()
    const t = ae.traces.pred_spy_buy
    ae.traces.pred_spy_fake = { ...t, source: { ...t.source, predictionId: 'pred_spy_fake' }, decisionReference: { ...t.decisionReference, predictionId: 'pred_spy_fake' } }
    ae.rankings = ae.rankings.map((r) => (r.ticker === 'SPY' ? { ...r, predictionId: 'pred_spy_fake' } : r))
    await tick('bot_r', 'SPY', 540)
    expect(await executions()).toHaveLength(0)
    expect(await decisions()).toHaveLength(0)
    expect(await skips()).toEqual(['research_evidence_unverified'])
  })

  it('sells an attributable position on SELL research, with linked evidence', async () => {
    await researchBot()
    // Prior broker-confirmed bot buy of IWM.
    await h.db.execution.create({ data: { id: 'exe_prior', userId: 'usr_a', portfolioId: 'por_usr_a', botId: 'bot_r', origin: 'bot', ticker: 'IWM', direction: 'buy', quantity: 20, price: 199, status: 'filled', filledQuantity: 20, filledPrice: 199, filledAt: new Date(T0.getTime() - 86_400_000), clientOrderId: 'tp_exe_prior' } })
    broker().positions.set('IWM', 20)

    await tick('bot_r', 'IWM', 200.5)
    const sell = (await executions({ direction: 'sell' }))[0]
    expect(sell).toMatchObject({ ticker: 'IWM', quantity: 20, signalScore: 0.9 })
    await drain()
    broker().fill(sell.clientOrderId, 20, 200.4)
    await drain()

    expect((await h.db.execution.findUnique({ where: { id: sell.id } })).status).toBe('filled')
    expect((await history(tokenA, sell.id)).body.data).toMatchObject({ status: 'verified_digest', predictionId: 'pred_iwm_sell' })
    const acct = await computeBotAccounting('bot_r')
    expect(acct.performance.realizedPnl).toBeCloseTo((200.4 - 199) * 20, 2)
    expect(acct.openPositions.IWM?.quantity ?? 0).toBe(0)
  })
})

// ── 2. Decisions that do not trade ───────────────────────────────────────────────

describe('research that does not justify a trade', () => {
  it('records rejected research with its verified evidence, once per window', async () => {
    await researchBot()
    await tick('bot_r', 'QQQ', 480)
    await tick('bot_r', 'QQQ', 480)
    const [d, ...rest] = await decisions()
    expect(rest).toHaveLength(0)
    expect(d.executionId ?? null).toBe(null)
    expect(d.metadata).toMatchObject({ decision: 'rejected', predictionId: 'pred_qqq_weak', decisionContext: { reason: 'below_min_confidence' } })
    expect(d.metadata.researchCanonicalJson).toBe(FIXTURES.traces.pred_qqq_weak.evidence.canonicalJson)
    expect(await executions()).toHaveLength(0)
    expect(broker().submitCalls).toBe(0)
  })

  it('suppresses stale research and research from a degraded run', async () => {
    await researchBot()
    await tick('bot_r', 'DIA', 420)
    expect((await decisions())[0].metadata).toMatchObject({ decision: 'suppressed', decisionContext: { reason: 'stale_prediction' } })

    ae.run = { intelligenceConfidenceTier: 'full', rankedUnderDegradedRun: true, runStatus: 'DEGRADED' }
    await tick('bot_r', 'SPY', 540)
    expect((await decisions()).map((d) => d.metadata.decisionContext.reason)).toEqual(['stale_prediction', 'degraded_research_run'])
    expect(await executions()).toHaveLength(0)
  })

  it('rejects when the price has drifted from the research entry', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 580)
    expect((await decisions())[0].metadata.decisionContext).toMatchObject({ reason: 'entry_price_drift', driftPct: 7.41 })
    expect(await executions()).toHaveLength(0)
  })

  it('records nothing it cannot verify, and skips tickers without research', async () => {
    await researchBot()
    ae.traces.pred_spy_buy.evidence.snapshot.confidence = 0.99 // tampered in transit
    await tick('bot_r', 'SPY', 540)
    ae.rankings = ae.rankings.filter((r) => r.ticker !== 'QQQ')
    await tick('bot_r', 'QQQ', 480)
    expect(await decisions()).toHaveLength(0)
    expect(await executions()).toHaveLength(0)
    expect((await skips()).sort()).toEqual(['no_research_prediction', 'research_evidence_unverified'])
  })

  it('does not trade on a portfolio risk pre-check block, and trades once it clears', async () => {
    await researchBot()
    h.risk.approved = false
    await tick('bot_r', 'SPY', 540)
    expect(await executions()).toHaveLength(0)
    expect(await decisions()).toHaveLength(0)
    const blocked = await h.db.botEvent.findFirst({ where: { botId: 'bot_r', type: 'execution_blocked_by_risk' } })
    expect(blocked.metadata.research).toMatchObject({ predictionId: 'pred_spy_buy' })

    h.risk.approved = true
    await tick('bot_r', 'SPY', 540)
    expect(await executions()).toHaveLength(1)
  })
})

// ── 3. Failure and recovery ──────────────────────────────────────────────────────

describe('failure and recovery', () => {
  it('fails closed while Alpha Engine is unreachable and recovers when it returns', async () => {
    await researchBot()
    ae.up = false
    await tick('bot_r', 'SPY', 540)
    expect(await executions()).toHaveLength(0)
    expect(await decisions()).toHaveLength(0)
    expect(await skips()).toEqual(['research_unavailable'])

    ae.up = true
    await tick('bot_r', 'SPY', 540)
    expect(await executions()).toHaveLength(1)
  })

  it('treats a trace-endpoint error as unavailable, not as a decision', async () => {
    await researchBot()
    ae.failTrace.add('pred_spy_buy')
    await tick('bot_r', 'SPY', 540)
    expect(await skips()).toEqual(['research_unavailable'])
    expect(await decisions()).toHaveLength(0)
  })

  it('lost broker response: reconciles by clientOrderId, never resubmits, evidence intact', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    const [exe] = await executions()
    broker().nextSubmit = 'lostResponse'
    await drain()
    // Unknown outcome → needs_reconciliation → adopted from the broker by clientOrderId.
    expect(await audits(exe.id)).toEqual(expect.arrayContaining(['submit_attempted', 'reconcile_required', 'reconciled']))
    broker().fill(exe.clientOrderId, 9, 540.1)
    await drain()
    expect(await h.db.execution.findUnique({ where: { id: exe.id } })).toMatchObject({ status: 'filled', filledQuantity: 9 })
    expect(broker().submitCalls).toBe(1)
    expect((await history(tokenA, exe.id)).body.data.status).toBe('verified_digest')
  })

  it('worker crash after claim: restart recovery completes the order with its evidence', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    const claimed = await claimNextExecution() // claimed, then the process dies
    expect(claimed).toBeTruthy()
    advance(130_000)
    eligibilityConfig.maxPriceAgeMs = 10 * 60_000
    await recoverStuckJobs()
    await drain()
    const exe = (await executions())[0]
    broker().fill(exe.clientOrderId, 9, 540)
    await drain()
    expect((await h.db.execution.findUnique({ where: { id: exe.id } })).status).toBe('filled')
    expect(broker().createdOrders).toBe(1)
    expect((await history(tokenA, exe.id)).body.data.status).toBe('verified_digest')
  })

  it('a failed link rolls back the execution and the accepted decision together', async () => {
    await researchBot()
    const real = h.db.botEvent.updateMany
    h.db.botEvent.updateMany = async () => { throw new Error('db write failed') }
    await tick('bot_r', 'SPY', 540)
    h.db.botEvent.updateMany = real
    expect(await executions()).toHaveLength(0)
    expect(await decisions()).toHaveLength(0)
    expect((await h.db.botEvent.findFirst({ where: { type: 'execution_failed' } })).detail).toMatch(/db write failed/)

    // Not marked as acted: the next evaluation trades it.
    advance(61_000)
    await tick('bot_r', 'SPY', 540)
    expect(await executions()).toHaveLength(1)
    expect((await history(tokenA, (await executions())[0].id)).body.data.status).toBe('verified_digest')
  })

  it('concurrent evaluations create exactly one execution and one accepted decision', async () => {
    await researchBot()
    priceCache.set('SPY', { last: 540, bid: 540, ask: 540 })
    const bot = await loaded('bot_r')
    await Promise.all([evaluateBot(bot, 'SPY'), evaluateBot(bot, 'SPY'), evaluateBot(bot, 'SPY')])
    expect(await executions()).toHaveLength(1)
    expect((await decisions()).filter((d) => d.metadata.decision === 'accepted')).toHaveLength(1)
  })
})

// ── 4. The final boundary protects audit integrity ──────────────────────────────

describe('final order-eligibility boundary for research-driven orders', () => {
  it('refuses an order whose archived evidence was altered after the decision', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    const [exe] = await executions()
    const [d] = await decisions()
    await h.db.botEvent.update({ where: { id: d.id }, data: { metadata: { ...d.metadata, researchEvidence: { ...d.metadata.researchEvidence, confidence: 0.99 } } } })
    await drain()
    expect(await h.db.execution.findUnique({ where: { id: exe.id } })).toMatchObject({ status: 'cancelled', cancelReason: 'refused:research_evidence_unverified' })
    expect(broker().submitCalls).toBe(0)
    expect((await history(tokenA, exe.id)).body.data.status).toBe('mismatch')
  })

  it('refuses a research-bot order with no linked decision', async () => {
    await researchBot()
    await h.db.execution.create({ data: { id: 'exe_unlinked', userId: 'usr_a', portfolioId: 'por_usr_a', botId: 'bot_r', origin: 'bot', ticker: 'SPY', direction: 'buy', quantity: 1, price: 540, status: 'queued', clientOrderId: 'tp_exe_unlinked' } })
    await drain()
    expect(await h.db.execution.findUnique({ where: { id: 'exe_unlinked' } })).toMatchObject({ status: 'cancelled', cancelReason: 'refused:research_evidence_unverified' })
    expect(broker().submitCalls).toBe(0)
  })

  it('emergency stop between decision and submit refuses the order; evidence stays verified', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    const [exe] = await executions()
    await activateEmergencyStop('usr_a', 'test')
    await drain()
    expect((await h.db.execution.findUnique({ where: { id: exe.id } })).status).toBe('cancelled')
    expect(broker().submitCalls).toBe(0)
    expect((await history(tokenA, exe.id)).body.data.status).toBe('verified_digest')
  })

  it('broker rejection and partial-then-cancel keep the research in trade history', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    const [rejected] = await executions()
    broker().nextSubmit = 'reject'
    await drain()
    expect((await h.db.execution.findUnique({ where: { id: rejected.id } })).status).toMatch(/failed|cancelled/)
    expect((await history(tokenA, rejected.id)).body.data.status).toBe('verified_digest')

    await researchBot('bot_r2')
    await tick('bot_r2', 'IWM', 200) // SELL research, but bot_r2 holds nothing → no order
    await tick('bot_r2', 'IWM', 200)
    expect(await executions({ botId: 'bot_r2' })).toHaveLength(0)
    expect(await skips('bot_r2')).toEqual(['no_position']) // throttled, not one per tick
  })

  it('partial fill then broker cancel: real partial quantity, research linked', async () => {
    await researchBot()
    await tick('bot_r', 'SPY', 540)
    const [exe] = await executions()
    await drain()
    broker().fill(exe.clientOrderId, 4, 540, 'canceled')
    await drain()
    expect(await h.db.execution.findUnique({ where: { id: exe.id } })).toMatchObject({ filledQuantity: 4 })
    expect((await computeBotAccounting('bot_r')).openPositions.SPY).toMatchObject({ quantity: 4 })
    expect((await history(tokenA, exe.id)).body.data).toMatchObject({ status: 'verified_digest', predictionId: 'pred_spy_buy' })
  })
})

// ── 5. Isolation ─────────────────────────────────────────────────────────────────

describe('multi-user isolation', () => {
  it('each user trades on their own broker and sees only their own trade history', async () => {
    await researchBot('bot_a', { userId: 'usr_a' })
    await researchBot('bot_b', { userId: 'usr_b' })
    await tick('bot_a', 'SPY', 540)
    await tick('bot_b', 'SPY', 540)
    await drain()
    const [ea] = await executions({ userId: 'usr_a' })
    const [eb] = await executions({ userId: 'usr_b' })
    expect(broker('usr_a').seenClientOrderIds).toEqual([ea.clientOrderId])
    expect(broker('usr_b').seenClientOrderIds).toEqual([eb.clientOrderId])

    expect((await history(tokenB, ea.id)).status).toBe(404)
    expect((await history(tokenA, eb.id)).status).toBe(404)
    const listB = await request(app.server).get('/api/executions').set(as(tokenB))
    expect(listB.body.data.map((e) => e.id)).toEqual([eb.id])
    // One user's acted prediction does not block another user's bot.
    expect((await decisions('bot_b')).map((d) => d.metadata.decision)).toEqual(['accepted'])
  })

  it('never uses live trading: every order went to the scripted paper broker', () => {
    expect(process.env.ALLOW_LIVE_TRADING).not.toBe('true')
  })
})

describe('edge over baseline (default policy)', () => {
  it('rejects research whose evidence shows no edge unless the bot opts in to simulate it', async () => {
    await researchBot('bot_default', { research: {} })
    await tick('bot_default', 'SPY', 540)
    expect(await executions({ botId: 'bot_default' })).toHaveLength(0)
    const [d] = await decisions('bot_default')
    expect(d.metadata).toMatchObject({ decision: 'rejected', decisionContext: { reason: 'no_edge_over_baseline', edgeOverBaseline: null } })
  })
})

